import React, { useState } from 'react';
import './App.css';

const App = () => {
  const questions = [
    {
      questionText: 'What is the capital of France?',
      options: ['Berlin', 'Madrid', 'Paris', 'Rome'],
      correctAnswer: 'Paris',
    },
    {
      questionText: 'Which planet is known as the Red Planet?',
      options: ['Earth', 'Mars', 'Jupiter', 'Saturn'],
      correctAnswer: 'Mars',
    },
    {
      questionText: 'What is the largest ocean on Earth?',
      options: ['Atlantic', 'Indian', 'Southern', 'Pacific'],
      correctAnswer: 'Pacific',
    },
    {
      questionText: 'Who wrote "Romeo and Juliet"?',
      options: ['Shakespeare', 'Dickens', 'Austen', 'Hemingway'],
      correctAnswer: 'Shakespeare',
    },
    {
      questionText: 'What is the chemical symbol for gold?',
      options: ['Ag', 'Au', 'Pb', 'Fe'],
      correctAnswer: 'Au',
    },
  ];

  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState('');
  const [correctAnswersCount, setCorrectAnswersCount] = useState(0);
  const [quizCompleted, setQuizCompleted] = useState(false);
  const [isIncorrect, setIsIncorrect] = useState(false);  // New state for incorrect answers

  const handleAnswerClick = (answer) => {
    if (!selectedAnswer) {
      setSelectedAnswer(answer);
      if (answer === questions[currentQuestionIndex].correctAnswer) {
        setCorrectAnswersCount(correctAnswersCount + 1);
        setIsIncorrect(false);  // Correct answer, so no incorrect state
      } else {
        setIsIncorrect(true);  // Incorrect answer, mark as incorrect
      }
    }
  };

  const handleNextClick = () => {
    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
      setSelectedAnswer('');
      setIsIncorrect(false);  // Reset incorrect state for the next question
    } else {
      setQuizCompleted(true);
    }
  };

  const calculateProgress = () => {
    return ((currentQuestionIndex + 1) / questions.length) * 100;
  };

  return (
    <div className="quiz-container">
      <h1>Quiz App</h1>

      {/* Progress Bar */}
      <div className="progress-bar">
        <div
          className="progress-bar-filled"
          style={{
            width: `${calculateProgress()}%`,
            backgroundColor: isIncorrect ? '#e74c3c' : '#2ecc71',  // Change color based on correct/incorrect answer
          }}
        ></div>
      </div>

      {!quizCompleted ? (
        <div className="question-container">
          <h2>{questions[currentQuestionIndex].questionText}</h2>
          <div className="options">
            {questions[currentQuestionIndex].options.map((option) => (
              <div
                key={option}
                className={`option ${option === selectedAnswer ? 'selected' : ''}`}
                onClick={() => handleAnswerClick(option)}
              >
                {option}
              </div>
            ))}
          </div>
          <button
            className={`next-btn ${selectedAnswer ? 'active' : ''}`}
            onClick={handleNextClick}
            disabled={!selectedAnswer}
          >
            Next
          </button>
        </div>
      ) : (
        <div className="result">
          <h2>Quiz Completed</h2>
          <div className="score-box">
            <p>Your score:</p>
            <p>{correctAnswersCount} / {questions.length}</p>
            <p>{((correctAnswersCount / questions.length) * 100).toFixed(2)}%</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;
